CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS citext;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email citext NOT NULL UNIQUE, password_hash text NOT NULL, display_name text NOT NULL CHECK (char_length(display_name) BETWEEN 1 AND 80), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS refresh_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash char(64) NOT NULL UNIQUE, user_agent text, ip_hash char(64), expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS refresh_sessions_user_idx ON refresh_sessions(user_id, expires_at DESC);
CREATE TABLE IF NOT EXISTS projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, title text NOT NULL CHECK (char_length(title) BETWEEN 1 AND 120), description text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS projects_owner_idx ON projects(owner_id, updated_at DESC);
CREATE TABLE IF NOT EXISTS canvases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL UNIQUE REFERENCES projects(id) ON DELETE CASCADE, viewport jsonb NOT NULL DEFAULT '{"x":0,"y":0,"zoom":1}'::jsonb, version bigint NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS canvas_nodes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), canvas_id uuid NOT NULL REFERENCES canvases(id) ON DELETE CASCADE, client_id text NOT NULL CHECK (char_length(client_id) BETWEEN 1 AND 120), node_type text NOT NULL, position jsonb NOT NULL, width double precision, height double precision, data jsonb NOT NULL DEFAULT '{}'::jsonb, revision bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(canvas_id, client_id));
CREATE INDEX IF NOT EXISTS canvas_nodes_canvas_idx ON canvas_nodes(canvas_id);
CREATE TABLE IF NOT EXISTS canvas_edges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), canvas_id uuid NOT NULL REFERENCES canvases(id) ON DELETE CASCADE, client_id text NOT NULL CHECK (char_length(client_id) BETWEEN 1 AND 120), source_client_id text NOT NULL, target_client_id text NOT NULL, edge_type text NOT NULL DEFAULT 'smoothstep', data jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(canvas_id, client_id));
CREATE INDEX IF NOT EXISTS canvas_edges_canvas_idx ON canvas_edges(canvas_id);
CREATE TABLE IF NOT EXISTS assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, owner_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind text NOT NULL, label text NOT NULL, object_key text NOT NULL, mime_type text NOT NULL, byte_size bigint NOT NULL CHECK (byte_size >= 0), sha256 char(64), metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS assets_project_idx ON assets(project_id, created_at DESC);
CREATE TABLE IF NOT EXISTS provider_credentials (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, provider text NOT NULL, base_url text NOT NULL, model text NOT NULL, ciphertext text NOT NULL, iv text NOT NULL, auth_tag text NOT NULL, key_version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id, provider));
CREATE TABLE IF NOT EXISTS graph_definitions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid REFERENCES projects(id) ON DELETE CASCADE, name text NOT NULL, version text NOT NULL, graph_ir jsonb NOT NULL, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id, name, version));
CREATE TABLE IF NOT EXISTS graph_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, requested_by uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, graph_name text NOT NULL, graph_version text NOT NULL, input jsonb NOT NULL, output jsonb, status text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','running','succeeded','failed','cancelled')), attempt integer NOT NULL DEFAULT 0, max_attempts integer NOT NULL DEFAULT 3, error text, locked_at timestamptz, locked_by text, created_at timestamptz NOT NULL DEFAULT now(), started_at timestamptz, finished_at timestamptz);
CREATE INDEX IF NOT EXISTS graph_runs_queue_idx ON graph_runs(status, created_at);
CREATE INDEX IF NOT EXISTS graph_runs_project_idx ON graph_runs(project_id, created_at DESC);
CREATE SEQUENCE IF NOT EXISTS graph_run_event_sequence;
CREATE TABLE IF NOT EXISTS graph_run_events (id bigserial PRIMARY KEY, run_id uuid NOT NULL REFERENCES graph_runs(id) ON DELETE CASCADE, sequence bigint NOT NULL DEFAULT nextval('graph_run_event_sequence'), event_type text NOT NULL, node_id text, payload jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(run_id, sequence));
CREATE INDEX IF NOT EXISTS graph_run_events_run_idx ON graph_run_events(run_id, sequence);
CREATE TABLE IF NOT EXISTS audit_logs (id bigserial PRIMARY KEY, actor_user_id uuid REFERENCES users(id) ON DELETE SET NULL, project_id uuid REFERENCES projects(id) ON DELETE SET NULL, action text NOT NULL, target_type text, target_id text, ip_hash char(64), metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_logs_actor_idx ON audit_logs(actor_user_id, created_at DESC);
